737: \section{Conclusion of the proof} \label{sec:conclusion}
738: \begin{definition}
739: Let $W$ be the subspace
740: \[W= \mathrm{Span}_{\mathbb{Z}}\left\{\linear_{\varphi}(\rho)\mid \rho\in\decomp_{\varphi} \text{ is wide} \right\}\]
741: \end{definition}
742: Recall the linear isomorphism $T:V\to \overline{\Lambda}\otimes \overline{\Lambda}$ defined by $T(A_{\lambda,\theta}) = \overline{s}_{\lambda}\otimes \overline{s}_{\theta}$.
743: \begin{lemma}
744: \label{lem:tall-dependent-on-wide}
745: Let $\varphi=(n,r,i,j,a,b,N)$ be valid with $N\leq \min(j,n-r-i)$. Then
746: $\linear_{\varphi}(\nu)\in W$
747: for any tall $\nu\in \decomp_{\varphi}$.
748: \end{lemma}
749: \begin{proof}
750: It is enough to show the analogous statement for tensors:
751: \[\mathrm{CP}(\overline{s}_{\nu_B}\otimes \overline{s}_{\nu_R})\in \mathrm{Span}_{\mathbb{Z}}\left\{\mathrm{CP}(\overline{s}_{\rho_B}\otimes \overline{s}_{\rho_R})\mid \rho\in\decomp_{\varphi} \text{ is wide} \right\} = T(W).\]
752: From $\varphi$ and $\nu$, suppose Algorithm~1 produced $\xi^{(0)},\ldots,\xi^{(K)}= \mathrm{Reduce}_{\varphi}(\nu)$. Then
753: \begin{align*}
754: \mathrm{CP}(\overline{s}_{\nu_B}\otimes \overline{s}_{\nu_R})&=\xi^{(0)}\\
755: &=\xi^{(K)} -\sum_{m=1}^K (\xi^{(m)}-\xi^{(m-1)})
756: \end{align*}
757: By Proposition \ref{prop:hopf-identity-application},
758: \[\xi^{(K)}= (-1)^{|\nu_B|+1}(1\otimes \overline{s}_{(\nu_B)'}).\]
759: We have $\nu_B'\subseteq (b^a)'=a^b$. Since $a+i\leq n-r$ and $b\leq j$, it follows that $\xi^{(K)}\in T(W)$.
760: It remains to show that each term $(\xi^{(m)}-\xi^{(m-1)})\in T(W)$. By definition,
761: \[\xi^{(m)}-\xi^{(m-1)} = -\gamma\mathrm{CP}(\overline{s}_{\lambda}\otimes (\overline{s}_{\mu^{(1)}}\cdots \overline{s}_{\mu^{(k)}})) \]
762: for some $\gamma\in \mathbb{Z}$ and partitions $\lambda,\mu^{(1)},\ldots,\mu^{(k)}$.
763: One observes from Algorithm~1 that \[|\lambda|+|\mu^{(1)}|+\cdots+|\mu^{(k)}|=N.\]
764: Since we are assuming $N\leq \min(j,n-r-i)$,
765: \[ \prod_{p=1}^k \overline{s}_{\mu^{(p)}}\in \mathrm{Span}_\mathbb{Z}\left\{\overline{s}_\theta\mid \theta\subseteq (n-r-i)^j\right\},\]
766: say
767: \[\prod_{p=1}^k \overline{s}_{\mu^{(p)}} = \sum_{\substack{\theta\subseteq (n-r-i)^j \\|\theta|=N-|\lambda|}} d_{\theta}\overline{s}_{\theta}. \]
768: Then if we expand, we obtain
769: \begin{align*}
770: \xi^{(m)}-\xi^{(m-1)}
771: &=-\gamma\mathrm{CP}(\overline{s}_{\lambda}\otimes (\overline{s}_{\mu^{(1)}}\cdots \overline{s}_{\mu^{(k)}}))\\
772: &=-\gamma\mathrm{CP}\biggr(\overline{s}_{\lambda}\otimes \sum_{\substack{\theta\subseteq (n-r-i)^j \\|\theta|=N-|\lambda|}} d_{\theta}\overline{s}_{\theta} \biggr)\\
773: &=-\gamma \sum_{\substack{\theta\subseteq (n-r-i)^j \\|\theta|=N-|\lambda|}} d_{\theta}\mathrm{CP}(\overline{s}_{\lambda}\otimes \overline{s}_{\theta}).
774: \end{align*}
775: Since $\lambda\subseteq \nu_B \subseteq b^a)$, each term $\mathrm{CP}(\overline{s}_{\lambda}\otimes \overline{s}_{\theta})$ is of the form $\mathrm{CP}(\overline{s}_{\rho_B}\otimes \overline{s}_{\rho_R})$ with $\rho\in\decomp_{\varphi}$ wide, it follows that $\xi^{(m)}-\xi^{(m-1)} \in T(W)$.
776: \end{proof}
777: \begin{lemma}
778: \label{lem:restricting-equations}
779: Suppose $\varphi=(n,r,i,j,a,b,N)$ be valid. Set $\widehat{\varphi}=(\widehat{n},\widehat{r},i,\widehat{j},a,b,N)$ where $\widehat{n}=4^qn$, $\widehat{r}=2^q r$, and $\widehat{j}=2^q j$ for $q\in {\mathbb N}$. Fix any $\nu\in \decomp_{\varphi}$, and let $\widehat{\nu}\in\decomp_{\widehat{\varphi}}$ be the partition with
780: \[\widehat{\nu}_B=\nu_B \quad\mbox{and}\quad \widehat{\nu}_R=\nu_R.\]
781: Then setting the variables
782: \[\{A_{\lambda,\theta} \mid \lambda\nsubseteq b^a \mbox{ or } \theta\nsubseteq (n-r-i)^j \}\]
783: to zero in $\linear_{\widehat{\varphi}}(\widehat{\nu})$ yields exactly $\linear_{\varphi}(\nu)$.
784: \end{lemma}
785: \begin{proof}
786: It suffices to note that
787: \[c_{(i^j,\lambda),\theta}^{\nu}= c_{(i^{\widehat{j}}\lambda),\theta}^{\widehat{\nu}}\]
788: by Theorem \ref{thm:pictures}, since the skew shapes $\nu/(i^j,\lambda)$ and $\widehat{\nu}/(i^{\widehat{j}}\lambda)$ are (essentially) the same.
789: \end{proof}

300: The following definition records the assumptions on the parameters used in the preceding considerations.
301: \begin{definition}
302: Call an integer tuple $\varphi=(n,r,i,j,a,b,N)$ \emph{valid} if $n,r,i,j,a,b,N\geq 1$ with
303: \[r<n,\quad a+j\leq r,\quad a+i\leq n-r,\quad b\leq i,j,\quad\mbox{and}\quad N\leq ab. \]
304: \end{definition}
305: Due to vanishing of Littlewood--Richardson coefficients, not all partitions $\nu\subseteq (n-r)^r$ contribute meaningfully to (\ref{eqn:eqs}).
306: \begin{definition}
307: Call a partition $\nu$ with $i^j\subseteq\nu\subseteq (n-r)^r$ and $|\nu|=ij+N$ \emph{allowable}.
308: \end{definition}
309: When $\nu$ is not allowable, both $\chi(\nu)$ and all the Littlewood--Richardson coefficients $c_{(i^j,\lambda),\theta}^{\nu}$ vanish. In this case both sides of the corresponding equation in (\ref{eqn:eqs}) are zero, so we can assume that $\nu$ is always allowable in~(\ref{eqn:eqs}). We will actually show that the equations (\ref{eqn:eqs}) are inconsistent by focusing on a smaller subset of them.
310: \begin{definition}
311: Call an allowable partition $\nu$ \emph{decomposable} if $\nu_{j+1}\leq b$ (taking $\nu_{j+1}=0$ if $\ell(\nu)= j$), and $\ell(\nu)\leq j+a$. Write $\decomp_{\varphi}$ for the set of decomposable partitions $\nu$. We will decompose any $\nu\in\decomp_{\varphi}$ into 3 smaller partitions via Figure \ref{fig:decomposition}.
312: \end{definition}
313: We will similarly say that an equation in (\ref{eqn:eqs}) is \emph{decomposable} if the partition $\nu$ it corresponds to is decomposable.
314: \begin{figure}[ht]
315: \begin{center}
316: \includegraphics{Images/nu_decomposition_scaled.pdf}
317: \end{center}
318: \caption{}
319: \label{fig:decomposition}
320: \end{figure}
321: We divide the decomposable partitions into two groups.
322: \begin{definition}
323: We say a decomposable partition $\nu$ is \emph{tall} if $\nu_1=i$ (so $\nu_R$ is empty), and \emph{wide} otherwise.
324: \end{definition}
325: Similarly, refer to the equation of a tall (resp.\ wide) partition $\nu$ as tall (resp.\ wide).
326: \begin{lemma}
327: \label{lem:implication-of-syzygy}
328: Suppose for some valid $\varphi=(n,r,i,j,a,b,N)$ there is a homogeneous syzygy of degree $N$ in $\overline{\Lambda}$ of the form
329: \[\sum_{\substack{\lambda\subseteq b^a\\|\lambda|=N}}\overline{s}_{(i^j,\lambda)}f_{\lambda}=\sum_{\substack{\lambda\subseteq b^a\\|\lambda|<N }}f_{\lambda}\overline{s}_{(i^j,\lambda)}\]
330: with the left-hand side nonzero.
331: Then the decomposable equations
332: \begin{equation}
333: \label{eqn:decomposable}
334: \biggr\{ \sum_{\substack{\lambda\subseteq b^a\\|\lambda|<N }}\sum_{\substack{\theta\subseteq (n-r)^r\\|\theta|=N-|\lambda|}} c_{(i^j,\lambda),\theta}^{\nu} \, A_{\lambda,\theta}=\chi(\nu)\,\biggr| \,\nu\in \decomp_{\varphi} \biggr\}
335: \end{equation}
336: are consistent, where $\chi(\nu)\in\mathbb{Z}$ is defined for $\nu\in \decomp_{\varphi}$ by
337: \[\chi(\nu)=\begin{cases}
338: f_{\nu_B} &\mbox{ if $\nu$ is tall,}\\
339: 0 &\mbox{ if $\nu$ is wide.}
340: \end{cases} \]

625: \begin{proof}It follows from Proposition~\ref{clm:2} that during the algorithm, the only cancellation that occurs in an update
626: \begin{equation}
627: \label{eqn:theupdate}
628: \xi^{(m)}=\xi^{(m-1)}-\gamma\mathrm{CP}(\overline{s}_{\lambda}\otimes (\overline{s}_{\mu^{(1)}}\cdots \overline{s}_{\mu^{(k)}}))
629: \end{equation}
630: is the cancellation of the term $\gamma\overline{s}_{\lambda}\otimes (\overline{s}_{\mu^{(1)}}\cdots \overline{s}_{\mu^{(k)}})$ in $\xi^{(m-1)}$, and its negative in $\gamma\mathrm{CP}(\overline{s}_{\lambda}\otimes (\overline{s}_{\mu^{(1)}}\cdots \overline{s}_{\mu^{(k)}}))$. Moreover, the algorithm only can
631: eliminate a term $\gamma\overline{s}_{\lambda}\otimes (\overline{s}_{\mu^{(1)}}\cdots \overline{s}_{\mu^{(k)}})$ with $|\lambda|>1$ by the update step
632: (\ref{eqn:theupdate}). Therefore the order in which we compute the update steps (\ref{eqn:theupdate}) does not effect the output.\end{proof}

